async function drivePost(payload){
  const response=await fetch(SALES_DRIVE_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify(payload),redirect:"follow"});
  if(!response.ok)throw new Error(`Google respondió ${response.status}`);
  const result=await response.json();if(!result.ok)throw new Error(result.error||"Drive rechazó la actualización.");return result;
}
function driveSaleChanges(sale,client){return {FECHA:sale.fecha||"",EMPRESA:client.razon||"",OV:sale.ov||"",FACTURA:sale.factura||"","DESCRIPCIÓN":sale.detalle||"",CANTIDAD:sale.cantidad||"",ESTADO:sale.estadoDrive||"PENDIENTE",RUC:client.ruc||"","ESTADO PAGO":sale.estadoPago==="pagado"?"PAGADO":"PENDIENTE",nota:sale.nota||""};}
async function pushSaleToDrive(sale,client,extra={}){if(!sale.sourceId)return;await drivePost({action:"actualizar",id:String(sale.sourceId),changes:{...driveSaleChanges(sale,client),...extra}});}
onSnapshot(clientsRef,snapshot=>{const all=snapshot.docs.map(d=>({id:d.id,...d.data()}));state.deletedSourceIds=new Set(all.filter(c=>c.eliminado).flatMap(c=>c.sourceIds||[]).map(String));state.clients=all.filter(c=>!c.eliminado);save();render();setCloudStatus("Sincronizado");},firebaseError);
onSnapshot(shipmentsRef,snapshot=>{state.shipments=snapshot.docs.map(d=>({id:d.id,...d.data()}));save();render();setCloudStatus("Sincronizado");},firebaseError);

