function openGlobalShipmentForm(preselectedClientId=""){const series=state.clients.flatMap(client=>clientSeries(client).map(value=>({value,client}))).sort((a,b)=>a.value.localeCompare(b.value));modal("Crear envío",`<form class="form" id="shipment-form"><input type="hidden" name="shipmentId" value=""><label>Cliente<select name="clientId" required><option value="">Buscar y seleccionar cliente</option>${state.clients.slice().sort((a,b)=>a.razon.localeCompare(b.razon)).map(client=>`<option value="${client.id}" ${String(client.id)===String(preselectedClientId)?"selected":""}>${esc(client.razon)} · ${esc(client.ruc)}</option>`).join("")}</select></label><label>Fecha en que se envió<input name="fecha" type="date" value="${today()}" required></label><label>Serie enviada<input name="serie" data-global-series list="all-system-series" placeholder="Busca una serie de todo el sistema"><small>Al seleccionar una serie, se seleccionará automáticamente su cliente.</small></label><datalist id="all-system-series">${series.map(item=>`<option value="${esc(item.value)}" label="${esc(item.client.razon)} · ${esc(item.client.ruc)}">`).join("")}</datalist><label>Tracking / guía<input name="tracking" placeholder="Se completará al detectar el QR"></label><label>Adjuntar imagen o PDF<input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"><small>Al seleccionar uno se leerá automáticamente el QR. Máximo 4 MB.</small></label><div id="qr-status" class="qr-status"></div><label>Observación<textarea name="nota" rows="3" placeholder="Opcional"></textarea></label><button>Guardar envío</button></form>`);}
function currentTime(){const now=new Date();return `${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;}
function followupHistory(client){return (Array.isArray(client.seguimientos)?client.seguimientos:[]).slice().sort((a,b)=>`${b.fecha||""}T${b.hora||""}`.localeCompare(`${a.fecha||""}T${a.hora||""}`));}
function followupLogSection(c){const items=followupHistory(c);return `<section class="contact-followup-section"><div class="contact-followup-heading"><div><span class="equipment-kicker">CONTACTO CON EL CLIENTE</span><h3>Historial de seguimiento</h3><p>Registra llamadas, correos, WhatsApp y coordinaciones.</p></div><span class="followup-log-total">${items.length}</span></div><div class="followup-log-layout"><form id="followup-log-form" class="followup-log-form"><input type="hidden" name="clientId" value="${c.id}"><div class="form-grid"><label>Fecha<input name="fecha" type="date" value="${today()}" required></label><label>Hora<input name="hora" type="time" value="${currentTime()}" required></label></div><label>Medio de contacto<select name="medio" required><option value="LLAMADA">Llamada</option><option value="CORREO">Correo</option><option value="WHATSAPP">WhatsApp</option><option value="REUNIÓN">Reunión</option><option value="OTRO">Otro</option></select></label><label>Nota de seguimiento<textarea name="nota" rows="4" required placeholder="Ej. Se llamó al cliente; confirmó que revisará la propuesta mañana."></textarea></label><button>+ Registrar seguimiento</button></form><div class="followup-log-list">${items.map(item=>`<article class="followup-log-item"><div><span class="followup-log-method">${esc(item.medio||"OTRO")}</span><b>${formatDate(item.fecha)} · ${esc(item.hora||"")}</b></div><p>${esc(item.nota||"")}</p><button type="button" class="danger-link" data-action="delete-followup" data-client="${c.id}" data-followup="${esc(item.id)}">Eliminar</button></article>`).join("")||'<div class="followup-log-empty">Todavía no hay contactos registrados.</div>'}</div></div></section>`;}
function openAdvisorForm(clientId,saleId){const c=clientById(clientId),sale=clientSales(c).find(item=>String(item.id)===String(saleId));if(!c||!sale)return;modal(`Asignar asesor · ${c.razon}`,`<form class="form" id="advisor-form"><input type="hidden" name="clientId" value="${c.id}"><input type="hidden" name="saleId" value="${esc(sale.id)}"><div class="client-summary"><b>${esc(sale.factura||sale.detalle||"Venta")}</b><span>${formatDate(sale.fecha)} · Selecciona al asesor responsable de esta venta.</span></div><label>Asesor<select name="asesor" required><option value="">Seleccionar asesor</option>${SALES_ADVISORS.map(value=>`<option value="${value}" ${sale.asesor===value?"selected":""}>${value}</option>`).join("")}</select></label><button>Guardar asesor</button></form>`);}
function openGlobalSaleSelector(){modal("Nueva venta",`<form class="form" id="choose-sale-client-form"><label>Cliente<select name="clientId" required><option value="">Seleccionar cliente</option>${state.clients.slice().sort((a,b)=>a.razon.localeCompare(b.razon)).map(client=>`<option value="${client.id}">${esc(client.razon)} · ${esc(client.ruc)}</option>`).join("")}</select></label><button>Continuar con la venta</button></form>`);}
function openClient(id){const c=clientById(id);if(!c)return;const list=clientShipments(id),series=clientSeries(c),sales=clientSales(c).slice().sort((a,b)=>String(b.fecha||"").localeCompare(String(a.fecha||""))),pending=sales.filter(sale=>sale.estadoPago!=="pagado").length;modal(c.razon,`<div class="client-header"><div><span class="label">RUC</span><b>${esc(c.ruc)}</b></div><div><span class="label">CONTACTOS</span>${contactDetails(c)}</div><div class="client-actions"><button class="whatsapp-btn" data-action="whatsapp" data-id="${c.id}">${whatsappIcon} WhatsApp</button><button class="primary dark" data-action="new-shipment" data-id="${c.id}">+ Agregar envío</button></div></div><section class="sales-section"><div class="sales-heading"><div><span class="equipment-kicker">CONTROL COMERCIAL</span><h3>Ventas de equipos</h3><p>Registra la venta, confirma el pago y luego asigna sus series.</p></div><div class="sales-heading-actions"><span class="pending-total">${pending} pendientes</span><button class="primary dark" data-action="new-sale" data-id="${c.id}">+ Nueva venta</button></div></div><div class="sales-list">${sales.map(sale=>saleRow(sale,c)).join("")||'<div class="sales-empty">Todavía no hay ventas registradas. Las series aparecerán debajo para asociarlas cuando corresponda.</div>'}</div></section>${followupLogSection(c)}<section class="equipment-section"><div class="equipment-heading"><div><span class="equipment-kicker">INVENTARIO DEL CLIENTE</span><h3>Todas las series</h3><p>Consulta cuáles tienen una venta asociada y asigna las que todavía están libres.</p></div><span class="series-total">${series.length}</span></div><form id="series-form" class="series-inline"><input type="hidden" name="clientId" value="${c.id}"><input name="series" placeholder="Agregar una nueva serie" autocomplete="off" required><button>+ Agregar serie</button></form><div class="series-inventory">${series.map(value=>inventorySeriesRow(value,c,sales)).join("")||'<span class="series-empty">Este cliente todavía no tiene series registradas.</span>'}</div></section><h3 class="subheading">Historial de envíos</h3><div class="shipment-list">${list.map(s=>shipmentRow(s,c,true)).join("")||'<div class="empty">Todavía no hay envíos registrados para este cliente.</div>'}</div>`,true);}
const openClientBase=openClient;
openClient=function(id){openClientBase(id);const actions=$("#modal-content .client-actions");if(actions){const button=document.createElement("button");button.type="button";button.className="delete-client-btn";button.dataset.action="delete-client";button.dataset.id=String(id);button.textContent="Eliminar cliente";actions.append(button);}};
function contactDetails(c){const contacts=Array.isArray(c.contactos)&&c.contactos.length?c.contactos:[{telefono:c.contacto,correo:c.correo}];return `<div class="contact-list">${contacts.map(contact=>`<span><b>${esc(`${contact.nombre||""} ${contact.apellido||""}`.trim())||"Contacto"}</b><small>${esc(contact.telefono||"")}${contact.telefono&&contact.correo?" · ":""}${esc(contact.correo||"")}</small></span>`).join("")}</div>`;}
function inventorySeriesRow(value,c,sales){const sale=sales.find(item=>(item.series||[]).some(series=>normalize(series)===normalize(value)));return `<div class="inventory-series-row"><b>${esc(value)}</b>${sale?`<span class="series-sale-status linked">${formatDate(sale.fecha)} · ${esc(sale.detalle)||"Venta asociada"}</span>`:`<span class="series-sale-status free">Sin venta</span><button data-action="assign-existing-series" data-client="${c.id}" data-series="${esc(value)}">Asignar a venta</button><button class="remove-series-btn" title="Quitar serie" data-action="delete-client-series" data-id="${c.id}" data-series="${esc(value)}">×</button>`}</div>`;}
function followupPending(sale){return !["INSTALADO","CAPACITADO"].includes(sale?.estadoSeguimiento);}
function followupSummary(sale){const status=sale.estadoSeguimiento||"POR DEFINIR",pending=followupPending(sale);return `<div class="sale-followup ${pending?"pending":"done"}"><span class="label">ESTADO DEL SEGUIMIENTO</span><b>${esc(status)}</b></div>`;}
function saleRow(sale,c){const paid=sale.estadoPago==="pagado",series=Array.isArray(sale.series)?sale.series:[],info=Array.isArray(sale.seriesInfo)?sale.seriesInfo:[];return `<article class="sale-row"><div class="sale-main"><div><span class="label">FECHA DE VENTA</span><b>${formatDate(sale.fecha)}</b></div><div><span class="label">OV / FACTURA</span><b>${esc(sale.ov)||"—"} / ${esc(sale.factura)||"—"}</b></div><div><span class="label">DESCRIPCIÓN / CANTIDAD</span><b>${esc(sale.detalle)||"Venta de equipos"}${sale.cantidad?` · ${esc(sale.cantidad)} und.`:""}</b></div><span class="payment-badge ${paid?"paid":"pending"}">${paid?"Pagado":"Pendiente"}</span></div>${sale.nota?`<p class="sale-note"><b>Nota:</b> ${esc(sale.nota)}</p>`:""}<div class="sale-series"><span class="label">SERIES Y ESTADO LOGÍSTICO</span><div class="series-chips">${series.map(value=>{const detail=info.find(item=>normalize(item.numero)===normalize(value))||{};return `<button class="series-chip sale series-status-button" data-action="edit-series-status" data-client="${c.id}" data-sale="${esc(sale.id)}" data-series="${esc(value)}"><b>${esc(value)}</b><small>${esc(detail.estado||"PENDIENTE")}${detail.fechaEntrega?` · ${formatDate(detail.fechaEntrega)}`:""}</small></button>`;}).join("")||'<span class="series-empty">Sin series asignadas</span>'}</div></div><div class="sale-controls"><button class="edit-sale-btn" data-action="edit-sale" data-client="${c.id}" data-sale="${esc(sale.id)}">Editar venta</button><button class="edit-sale-btn" data-action="copy-sale" data-client="${c.id}" data-sale="${esc(sale.id)}">Copiar venta</button>${sale.comprobantePago?`<button class="payment-proof-btn" data-action="open-payment-proof" data-client="${c.id}" data-sale="${esc(sale.id)}">Ver comprobante</button>`:""}<button class="delete-sale-btn" data-action="delete-sale" data-client="${c.id}" data-sale="${esc(sale.id)}">Eliminar venta</button><button class="payment-toggle ${paid?"paid":""}" data-action="toggle-sale-payment" data-client="${c.id}" data-sale="${esc(sale.id)}">${paid?"Marcar pendiente":"Marcar como pagado"}</button>${paid?`<button class="assign-series-btn" data-action="assign-sale-series" data-client="${c.id}" data-sale="${esc(sale.id)}">+ Asignar series</button>`:'<span class="sale-waiting">Confirma el pago para asignar series</span>'}</div></article>`;}
const baseSaleRow=saleRow;
saleRow=(sale,c)=>baseSaleRow(sale,c).replace('<div class="sale-series">',`${followupSummary(sale)}<div class="advisor-badge"><span class="label">ASESOR</span><b>${esc(sale.asesor||"SIN ASIGNAR")}</b><button type="button" data-action="assign-advisor" data-client="${c.id}" data-sale="${esc(sale.id)}">${sale.asesor?"Cambiar asesor":"Asignar asesor"}</button></div>${normalize(sale.estadoDrive||"PENDIENTE")!=="pendiente"?`<div class="drive-state-badge"><span class="label">ESTADO EN DRIVE</span><b>${esc(sale.estadoDrive)}</b></div>`:""}<div class="sale-series">`);
function shipmentRow(s,c,actions=false){const isImage=s.documento?.tipo?.startsWith("image/");return `<article class="shipment-row"><div class="shipment-date"><b>${formatDate(s.fecha)}</b><span>${esc(s.serie)||"Sin serie"}</span></div><div><span class="label">TRACKING</span><b>${esc(s.tracking)||"Sin tracking"}</b><small>${esc(s.nota)||""}</small></div><div><span class="label">ARCHIVO</span>${s.documento?`<button class="link-btn" data-action="open-file" data-id="${s.id}">${isImage?"🖼️":"📄"} ${esc(s.documento.nombre)}</button>`:"<span>Sin archivo</span>"}</div>${actions?`<div class="shipment-actions"><button class="edit-link" data-action="edit-shipment" data-id="${s.id}" data-client="${c.id}">Editar</button><button class="danger-link" data-action="delete-shipment" data-id="${s.id}" data-client="${c.id}">Eliminar</button></div>`:""}</article>`;}

