["filter-sales","filter-payment","filter-followup-type","filter-followup-status","filter-logistics","filter-recent","filter-date-from","filter-date-to","filter-order"].forEach(id=>$("#"+id)?.addEventListener("change",()=>{state.clientPage=1;renderClients();}));
