function renderSpreadsheetClients(){const q=normalize($("#client-search")?.value),salesFilter=$("#filter-sales")?.value||"",paymentFilter=$("#filter-payment")?.value||"",followupType=$("#filter-followup-type")?.value||"",followupStatus=$("#filter-followup-status")?.value||"",logisticsFilter=$("#filter-logistics")?.value||"",recentDays=Number($("#filter-recent")?.value)||0,dateFrom=$("#filter-date-from")?.value||"",dateTo=$("#filter-date-to")?.value||"",order=$("#filter-order")?.value||"newest",recentCutoff=recentDays?new Date(Date.now()-(recentDays-1)*86400000).toISOString().slice(0,10):"";let entries=state.clients.flatMap(client=>{const sales=clientSales(client);return sales.length?sales.map(sale=>({client,sale})):[{client,sale:null}];});entries=entries.filter(({client,sale})=>{const contact=spreadsheetContact(client),text=normalize(`${client.ruc} ${client.razon} ${contact.nombre} ${contact.correo} ${contact.telefono} ${clientSeries(client).join(" ")} ${sale?`${sale.ov||""} ${sale.factura||""} ${sale.detalle||""} ${sale.asesor||""} ${sale.estadoSeguimiento||""} ${(sale.series||[]).join(" ")}`:""}`);if(q&&!text.includes(q))return false;if(salesFilter==="with"&&!sale)return false;if(salesFilter==="without"&&sale)return false;if(paymentFilter==="pending"&&(!sale||sale.estadoPago==="pagado"))return false;if(paymentFilter==="paid"&&(!sale||sale.estadoPago!=="pagado"))return false;if(followupType==="without"&&(!sale||sale.tipoSeguimiento))return false;if(followupType&&followupType!=="without"&&sale?.tipoSeguimiento!==followupType)return false;if(followupStatus==="pending"&&(!sale||!followupPending(sale)))return false;if(followupStatus&&followupStatus!=="pending"&&(sale?.estadoSeguimiento||"POR DEFINIR")!==followupStatus)return false;const logistics=sale?.seriesInfo||[];if(logisticsFilter==="without"&&((sale?.series||[]).length||logistics.length))return false;if(logisticsFilter&&logisticsFilter!=="without"&&!logistics.some(item=>normalize(item.estado)===normalize(logisticsFilter)))return false;if(recentCutoff&&(!sale||sale.fecha<recentCutoff))return false;if(dateFrom&&(!sale||sale.fecha<dateFrom))return false;if(dateTo&&(!sale||sale.fecha>dateTo))return false;return true;}).sort((a,b)=>order==="oldest"?String(a.sale?.fecha||"").localeCompare(String(b.sale?.fecha||"")):String(b.sale?.fecha||"").localeCompare(String(a.sale?.fecha||"")));const totalPages=Math.max(1,Math.ceil(entries.length/state.clientPageSize));state.clientPage=Math.min(Math.max(1,state.clientPage),totalPages);const start=(state.clientPage-1)*state.clientPageSize,visible=entries.slice(start,start+state.clientPageSize);$("#clients-table").innerHTML=visible.map(({client,sale})=>spreadsheetSaleRow(client,sale)).join("")||'<tr><td colspan="17" class="empty">No se encontraron registros con los filtros seleccionados.</td></tr>';const summary=$("#filter-summary");if(summary)summary.textContent=`${entries.length} registros · edición tipo Excel · ${order==="oldest"?"más antiguos primero":"más recientes primero"}`;renderClientPagination(entries.length,totalPages,start,visible.length);}
async function saveSpreadsheetSaleRow(button){const row=button.closest("tr"),client=clientById(row?.dataset.client),saleId=row?.dataset.sale;if(!row||!client||!saleId)return;const value=name=>row.querySelector(`[data-field="${name}"]`)?.value?.trim()||"",condition=value("estadoPago"),diasCredito=value("diasCredito");if(condition==="credito"&&(!diasCredito||Number(diasCredito)<1))return alert("Indica cuántos días de crédito tiene la venta.");const series=[...new Map(value("series").split(/[\n,;]+/).map(item=>item.trim()).filter(Boolean).map(item=>[normalize(item),item])).values()],contactName=value("contactoNombre"),correo=value("correo").toLowerCase(),telefono=cleanPhone(value("telefono")),contacts=Array.isArray(client.contactos)?client.contactos.slice():[],first=contacts[0]||{};if(contactName||correo||telefono)contacts[0]={...first,nombre:contactName,apellido:"",correo,telefono};const ventas=clientSales(client).map(sale=>String(sale.id)!==String(saleId)?sale:{...sale,fecha:value("fecha"),ov:value("ov"),factura:value("factura"),detalle:value("detalle"),cantidad:value("cantidad"),asesor:value("asesor"),estadoPago:condition==="pagado"?"pagado":"pendiente",condicionPago:condition,diasCredito:condition==="credito"?diasCredito:"",tipoSeguimiento:value("tipoSeguimiento")==="INSTALACIÓN"?"INSTALACIÓN":"ENVÍO",estadoSeguimiento:value("estadoSeguimiento")||"POR DEFINIR",nota:value("nota"),estadoFinal:value("estadoFinal"),series});const allSeries=[...new Map([...clientSeries(client),...series].map(item=>[normalize(item),item])).values()];try{button.disabled=true;button.textContent="Guardando...";setCloudStatus("Guardando fila...");await updateDoc(doc(db,"envioClientes",client.id),{razon:value("razon")||client.razon,contacto:telefono||client.contacto,correo:correo||client.correo||"",contactos:contacts,ventas,series:allSeries,actualizadoEn:serverTimestamp()});button.textContent="Guardado ✓";setCloudStatus("Sincronizado");setTimeout(()=>renderClients(),700);}catch(error){button.disabled=false;button.textContent="Guardar";firebaseError(error);}}
