function renderClientPagination(total,totalPages,start,visible){const el=$("#clients-pagination");if(!el)return;const from=total?start+1:0,to=start+visible;el.innerHTML=`<div class="pagination-summary">Mostrando <b>${from}–${to}</b> de <b>${total}</b> registros</div><div class="pagination-actions"><label>Por página <select id="client-page-size"><option value="10" ${state.clientPageSize===10?"selected":""}>10</option><option value="20" ${state.clientPageSize===20?"selected":""}>20</option><option value="50" ${state.clientPageSize===50?"selected":""}>50</option></select></label><button data-action="client-page" data-page="${state.clientPage-1}" ${state.clientPage===1?"disabled":""}>‹ Anterior</button><span>Página <b>${state.clientPage}</b> de ${totalPages}</span><button data-action="client-page" data-page="${state.clientPage+1}" ${state.clientPage===totalPages?"disabled":""}>Siguiente ›</button></div>`;}
function renderDashboard(){const now=new Date(),prefix=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;$("#stat-clients").textContent=state.clients.length;$("#stat-shipments").textContent=state.shipments.length;$("#stat-month").textContent=state.shipments.filter(s=>s.fecha.startsWith(prefix)).length;$("#stat-pdf").textContent=state.shipments.filter(s=>s.documento).length;const latest=state.shipments.slice().sort((a,b)=>b.fecha.localeCompare(a.fecha)).slice(0,5);$("#recent-list").innerHTML=latest.map(s=>{const c=clientById(s.clientId)||{};return shipmentRow(s,c);}).join("")||'<div class="empty">No hay envíos registrados.</div>';}
